import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

/**
 * Generates packages/cli/src/version.ts from packages/cli/package.json so the
 * CLI version (and the SEA binary's `--version`) has exactly one source of
 * truth. Runs as part of the cli build; the generated file is committed so
 * typecheck works from a fresh clone. A committed file that drifts from
 * package.json is caught by test/version.test.ts.
 */
const here = path.dirname(fileURLToPath(import.meta.url));
const pkgPath = path.join(here, "..", "packages", "cli", "package.json");
const outPath = path.join(here, "..", "packages", "cli", "src", "version.ts");

const pkg = JSON.parse(await readFile(pkgPath, "utf8"));
const content = `/* GENERATED by scripts/write-version.mjs from packages/cli/package.json — do not edit. */
export const CLI_VERSION = ${JSON.stringify(pkg.version)};
`;
await writeFile(outPath, content, "utf8");
console.log(`write-version: CLI_VERSION = ${pkg.version}`);
